style.css:
@-moz-document domain("roblox.com") {
body, .ng-scope, .container-main, .content, .content:before, .rbx-body, .rbx-main-content {
        background: transparent !important;
    }

    html, body {
        min-height: 100% !important;
    }

    html::before {
        content: "";
        position: fixed;
        inset: 0;
        background: url("https://i.pinimg.com/1200x/08/b6/18/08b618b21e11ab4b339f0e37ce4d0977.jpg") center/cover no-repeat;
        z-index: -9999;
        pointer-events: none;
    }
}
